import heapq

def match(orders):
    trades = []
    # order books: buy_book max-heap by (-price, seq), sell_book min-heap by (price, seq)
    buy_book = []
    sell_book = []
    seq_counter = 0
    # store order info: id -> [side, price, qty_remaining, seq, active]
    order_info = {}

    def add_resting(side, oid, price, qty, seq):
        info = [side, price, qty, seq, True]
        order_info[oid] = info
        if side == 'buy':
            heapq.heappush(buy_book, (-price, seq, oid))
        else:
            heapq.heappush(sell_book, (price, seq, oid))

    def clean_buy_top():
        while buy_book:
            negprice, seq, oid = buy_book[0]
            info = order_info.get(oid)
            if info is None or not info[4] or info[2] <= 0:
                heapq.heappop(buy_book)
                continue
            return True
        return False

    def clean_sell_top():
        while sell_book:
            price, seq, oid = sell_book[0]
            info = order_info.get(oid)
            if info is None or not info[4] or info[2] <= 0:
                heapq.heappop(sell_book)
                continue
            return True
        return False

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info is not None and info[4] and info[2] > 0:
                info[4] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0 and clean_sell_top():
                sprice, sseq, soid = sell_book[0]
                if typ != 'market' and price < sprice:
                    break
                info = order_info[soid]
                avail = info[2]
                trade_qty = min(remaining, avail)
                trades.append([oid, soid, sprice, trade_qty])
                remaining -= trade_qty
                info[2] -= trade_qty
                if info[2] <= 0:
                    info[4] = False
                    heapq.heappop(sell_book)
            if typ == 'limit' and remaining > 0:
                add_resting('buy', oid, price, remaining, seq_counter)
                seq_counter += 1
            # else discard remainder for ioc/market
        else:  # sell
            while remaining > 0 and clean_buy_top():
                negprice, bseq, boid = buy_book[0]
                bprice = -negprice
                if typ != 'market' and price > bprice:
                    break
                info = order_info[boid]
                avail = info[2]
                trade_qty = min(remaining, avail)
                trades.append([boid, oid, bprice, trade_qty])
                remaining -= trade_qty
                info[2] -= trade_qty
                if info[2] <= 0:
                    info[4] = False
                    heapq.heappop(buy_book)
            if typ == 'limit' and remaining > 0:
                add_resting('sell', oid, price, remaining, seq_counter)
                seq_counter += 1

    return trades

